INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Kunden- und Marktperspektive > Marketing & Verkaufsförderung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Marketingmaßnahmen immer auf die Zielgruppe abgestimmt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Effektivität hängt von Zielgruppenorientierung ab"}, {"text": "Nein", "correct": false, "because": "Zielgruppe ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Verkaufsförderung ohne Rücksicht auf den Markt erfolgreich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Marktbedingungen beeinflussen Erfolg"}, {"text": "Ja", "correct": false, "because": "Markt ist entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Marketing nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Unternehmen profitieren"}, {"text": "Ja", "correct": false, "because": "Universell anwendbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verkaufsförderungsmaßnahmen ohne Budgetplanung effektiv sein?', 2, '[{"text": "Nein", "correct": true, "because": "Budget bestimmt Umfang und Erfolg"}, {"text": "Ja", "correct": false, "because": "Planung ist nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Marketingstrategien immer langfristig ausgerichtet?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kurzfristige Kampagnen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt ist bei Marketingmaßnahmen am wichtigsten?', 3, '[{"text": "Zielgruppenansprache", "correct": true, "because": "Erhöht Wirksamkeit"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Verkaufsförderung primär?', 2, '[{"text": "Umsatzsteigerung", "correct": true, "because": "Fördert Käufe"}, {"text": "Kostensenkung", "correct": false, "because": "Sekundär"}, {"text": "Markenimage", "correct": false, "because": "Langfristig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist ein typisches Mittel der Verkaufsförderung?', 2, '[{"text": "Rabattaktionen", "correct": true, "because": "Anreiz für Käufe"}, {"text": "Farbgestaltung", "correct": false, "because": "Ästhetisch"}, {"text": "Logistikplanung", "correct": false, "because": "Operativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Marketingstrategie maßgeblich?', 3, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Orientierung am Markt"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferantenauswahl", "correct": false, "because": "Beschaffung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil von Marketing im IT-Bereich?', 2, '[{"text": "Kundengewinnung", "correct": true, "because": "Erhöht Marktreichweite"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Marketingstrategie?', 4, '[{"text": "Zielgruppenanalyse", "correct": true, "because": "Bestimmt Ansprache"}, {"text": "Werbemaßnahmen", "correct": true, "because": "Fördert Bekanntheit"}, {"text": "Budgetplanung", "correct": true, "because": "Finanzielle Grundlage"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen zählen zur Verkaufsförderung?', 3, '[{"text": "Rabatte", "correct": true, "because": "Anreiz für Käufe"}, {"text": "Sonderaktionen", "correct": true, "because": "Zeitlich begrenzt"}, {"text": "Kundenprämien", "correct": true, "because": "Belohnungssystem"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine effektive Marketingstrategie?', 3, '[{"text": "Kundengewinnung", "correct": true, "because": "Erhöht Marktanteil"}, {"text": "Markenbekanntheit", "correct": true, "because": "Stärkt Image"}, {"text": "Umsatzsteigerung", "correct": true, "because": "Fördert Verkäufe"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei Marketing und Verkaufsförderung auftreten?', 4, '[{"text": "Fehlende Zielgruppenansprache", "correct": true, "because": "Reduziert Wirkung"}, {"text": "Hohe Kosten", "correct": true, "because": "Budgetüberschreitung"}, {"text": "Unklare Botschaft", "correct": true, "because": "Verwirrt Kunden"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Verkaufsförderung?', 3, '[{"text": "Kundenbedürfnisse", "correct": true, "because": "Orientierung am Markt"}, {"text": "Wettbewerb", "correct": true, "because": "Bestimmt Maßnahmen"}, {"text": "Budget", "correct": true, "because": "Finanzielle Grenzen"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Marketing muss auf die Zielgruppe abgestimmt sein. b) Verkaufsförderung ist unabhängig vom Markt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zielgruppe ja, Markt wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rabatte sind eine typische Verkaufsförderungsmaßnahme. b) Marketing ist nur für große Unternehmen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rabatte ja, Marketing für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Zielgruppenanalyse ist ein Bestandteil des Marketings. b) Budgetplanung ist für Verkaufsförderung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analyse ja, Budget wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Marketingstrategien können kurzfristig sein. b) Verkaufsförderung zielt nicht auf Umsatzsteigerung ab.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kurzfristig ja, Umsatz Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenbedürfnisse beeinflussen die Marketingstrategie. b) Hohe Kosten sind kein Problem im Marketing.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bedürfnisse ja, Kosten relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

